package com.yeyamo_mobile.api.gamification_service.infrastructure.cache;import java.time.Duration;import java.util.*;import org.slf4j.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.stereotype.Component;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.gamification_service.application.GamificationView;import com.yeyamo_mobile.api.gamification_service.application.port.GamificationCachePort;
@Component public class RedisGamificationCacheAdapter implements GamificationCachePort{private static final Logger log=LoggerFactory.getLogger(RedisGamificationCacheAdapter.class);private final StringRedisTemplate redis;private final ObjectMapper mapper;private final Duration ttl;public RedisGamificationCacheAdapter(StringRedisTemplate r,ObjectMapper m,@Value("${gamification.cache.ttl-seconds:120}")long seconds){redis=r;mapper=m;ttl=Duration.ofSeconds(Math.max(1,seconds));}public Optional<GamificationView>get(String user){try{String value=redis.opsForValue().get(key(user));return value==null?Optional.empty():Optional.of(mapper.readValue(value,GamificationView.class));}catch(Exception e){log.debug("Gamification cache read unavailable: {}",e.getMessage());return Optional.empty();}}public void put(String user,GamificationView view){try{redis.opsForValue().set(key(user),mapper.writeValueAsString(view),ttl);}catch(Exception e){log.debug("Gamification cache write unavailable: {}",e.getMessage());}}public void evict(String user){try{redis.delete(key(user));}catch(RuntimeException e){log.debug("Gamification cache eviction unavailable: {}",e.getMessage());}}private String key(String user){return"gamification:view:"+user;}}
